import React from "react";

import styles from "./FUIButtonTile.module.css";

export interface FUIButtonTileProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: React.ReactNode;
  label: React.ReactNode;
  active?: boolean;
}

export function FUIButtonTile({
  icon,
  label,
  active = false,
  className = "",
  type = "button",
  ...props
}: FUIButtonTileProps) {
  return (
    <button
      type={type}
      className={`${styles.root} ${active ? styles.active : ""} ${className}`.trim()}
      {...props}
    >
      <div className={styles.content}>
        {icon ? <span className={styles.icon}>{icon}</span> : null}
        <strong className={styles.label}>{label}</strong>
      </div>
    </button>
  );
}

export default FUIButtonTile;

.root {
  appearance: none;
  width: var(--fui-tile-width, 120px);
  height: var(--fui-tile-height, 120px);
  min-width: var(--fui-tile-width, 120px);
  min-height: var(--fui-tile-height, 120px);
  flex-shrink: 0;
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
  padding: 0.5rem;
  position: relative;
  overflow: visible;
  font: inherit;
  text-align: center;
  transition:
    border-color 250ms ease-in-out,
    color 250ms ease-in-out;
}

.root::after {
  content: "";
  border-top: 0.5rem solid transparent;
  border-bottom: 0.5rem solid transparent;
  border-left: 0.5rem solid currentColor;
  transform: rotate(45deg);
  position: absolute;
  bottom: -0.2rem;
  right: 0.03rem;
  transition: border-color 250ms ease-in-out;
}

.root:hover,
.root:focus-visible,
.active {
  color: var(--accent-red);
  border-color: var(--accent-red);
}

.root:focus {
  outline: none;
}

.content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  margin: 0;
}

.label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  text-align: center;
  line-height: 1.2;
  font-weight: 700;
}

.icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.icon :global(svg) {
  width: 32px;
  height: 32px;
}

@media (max-width: 768px) {
  .root {
    --fui-tile-width: 90px;
    --fui-tile-height: 90px;
  }
}
